import Button from "@mui/material/Button";

export default function Translatebutton({ t, toggleLanguage }) {
  return (
    <div className="Translatebutton">
      <Button
        size="large"
        color="secondary"
        variant="contained"
        onClick={toggleLanguage}
      >
        {t("عربي")}{" "}
      </Button>
    </div>
  );
}
