import "./App.css";
import "../src/components/Mycomponents.css";
import { createTheme, ThemeProvider } from "@mui/material/styles";
import Container from "@mui/material/Container";
// Extermanel
import axios from "axios";
import moment from "moment";
import "moment/min/locales";
import { useTranslation } from "react-i18next";
import { useEffect, useState } from "react";

// {* My components * }

import { CARD } from "../src/components/CARD";
import { CityandTime } from "../src/components/City_and_time";
import { Temp } from "../src/components/Temp";
import { Claoud } from "../src/components/imageIcon";
import Translatebutton from "../src/components/TransleatBTN";

moment.locale("en");
// {* == My components == * }

const Them = createTheme({
  typography: {
    fontFamily: "IBM",
  },
});
let cancelaxios = null;

function App() {
  const { t, i18n } = useTranslation();
  const [local, setlocal] = useState("ar");
  const [DateAndTime, setDateAndTime] = useState();
  const [temperature, settemp] = useState({
    number: null,
    description: "",
    min: null,
    max: null,
    icon: null,
  });
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    i18n.changeLanguage(local);
    moment.locale(local);
    setDateAndTime(
      moment().format(
        local === "ar" ? "MMMM Do YYYY, h:mm:ss a" : "MMMM Do YYYY, h:mm:ss a",
      ),
    ); // Adjust format if needed for Arabic
  }, [local]);
  useEffect(() => {
    setDateAndTime(moment().format("MMMM Do YYYY, h:mm:ss a"));
    // Removed forced English change here
    axios
      .get(
        "https://api.openweathermap.org/data/2.5/weather?lat=25.276987&lon=55.296249&appid=44da5010c140e21088b60d5ea14ae4d8",
        {
          cancelToken: new axios.CancelToken((c) => {
            // مكتبة منها تجعلك تلغي اي طلب جديد من دون الحاجة لها عند فتح صغحة اخرى وتستخدم داحل
            //UseEffect.
            cancelaxios = c;
          }),
        },
      )
      .then(function (response) {
        // handle success
        const min = response.data.main.temp_min;
        const temp = response.data.main.temp;
        const max = response.data.main.temp_max;
        const description = response.data.weather[0].description;
        const icon = response.data.weather[0].icon;
        settemp({
          number: temp,
          description: description,
          min: min,
          max: max,
          icon: icon,
        });
        setLoading(false);
        console.log(response.data);
      })
      .catch(function (error) {
        // handle error
        console.log(error);
        setLoading(false);
      });
    // .finally(function () {
    //   // always executed
    // });
    return () => {
      //هذه يقوم ب الغأء ال اي بي أي بسسب ان الريندر يجعل الطلب يتجدد تلقائي من دون حاجة له
      cancelaxios();
    };
  }, []);

  // === Events Handler ======
  function toggleLanguage() {
    setlocal((prev) => (prev === "en" ? "ar" : "en"));
  }
  // =============End Events Handler ======
  return (
    <div className="App">
      <ThemeProvider theme={Them}>
        <Container maxWidth="sm">
          {/* Content Card */}
          <div className="CardCountener">
            {/* CARD */}
            <CARD local={local}>
              {/* CONTENT */}
              <div className="CONTENT">
                {/* CITY & TIME */}
                <CityandTime t={t} dateAndTime={DateAndTime} />
                {/* == CITY & TIME == */}
                <hr />

                {/* CONTAINER OF DEGREE + CLOUD ICON */}
                <div className="CONTENTofDEGREE">
                  {/* DEGREE & DESCRIPTION */}
                  <div>
                    {/* Temp */}
                    <Temp t={t} temperature={temperature} />
                    {/*======Temp */}
                  </div>

                  {/*== DEGREE & DESCRIPTION ==*/}
                  <Claoud />
                </div>
                {/* == CONTAINER OF DEGREE + CLOUD ICON == */}
              </div>
              {/* == CONTENT == */}
            </CARD>{" "}
            {/*=== CARD ===*/}
            {/* Translate button */}
            <Translatebutton t={t} toggleLanguage={toggleLanguage} />
            {/* == Translate button ==*/}
          </div>
          {/*=== Content Card ===*/}
        </Container>
      </ThemeProvider>
    </div>
  );
}

export default App;
